/**
 * The card's header: the title, the period, and one tile per headline stat.
 * Returns SVG fragments positioned inside the card.
 */
import { MARGIN, INNER_WIDTH } from "./layout.mjs";
import { formatValue, formatPercent, escapeXml } from "./format.mjs";

const INK = "#111827";
const MUTED = "#6b7280";
const TILE_FILL = "#f3f4f6";
const UP = "#15803d";
const DOWN = "#b91c1c";

const TITLE_BASELINE = 54;
const PERIOD_BASELINE = 74;

const TILE_TOP = 90;
const TILE_HEIGHT = 80;
const TILE_GAP = 12;
const TILE_RADIUS = 8;
const TILE_PAD = 14;
const LABEL_BASELINE = 24; // offsets from the tile top, the same in every tile
const VALUE_BASELINE = 54;
const CHANGE_BASELINE = 70;

export function renderHeader(data) {
  const n = data.stats.length;
  const tileWidth = (INNER_WIDTH - TILE_GAP * (n - 1)) / n;
  const out = [
    `<text x="${MARGIN}" y="${TITLE_BASELINE}" font-size="20" font-weight="600" fill="${INK}">${escapeXml(data.title)}</text>`,
    `<text x="${MARGIN}" y="${PERIOD_BASELINE}" font-size="12" fill="${MUTED}">${escapeXml(data.period)}</text>`,
  ];
  data.stats.forEach((stat, i) => {
    const x = MARGIN + i * (tileWidth + TILE_GAP);
    const tx = x + TILE_PAD;
    const up = stat.delta >= 0;
    const colour = up ? UP : DOWN;
    out.push(
      `<rect x="${x}" y="${TILE_TOP}" width="${tileWidth}" height="${TILE_HEIGHT}" rx="${TILE_RADIUS}" ry="${TILE_RADIUS}" fill="${TILE_FILL}"/>`,
      `<text x="${tx}" y="${TILE_TOP + LABEL_BASELINE}" font-size="10" font-weight="600" letter-spacing="0.6" fill="${MUTED}">${escapeXml(stat.label.toUpperCase())}</text>`,
      `<text x="${tx}" y="${TILE_TOP + VALUE_BASELINE}" font-size="28" font-weight="700" fill="${INK}">${escapeXml(formatValue(stat.value, stat.unit))}</text>`,
      `<text x="${tx}" y="${TILE_TOP + CHANGE_BASELINE}" font-size="11" font-weight="600" fill="${colour}">${up ? "▲" : "▼"} ${formatPercent(stat.delta)} <tspan font-weight="400" fill="${MUTED}">vs previous period</tspan></text>`,
    );
  });
  return out.join("");
}
EOF
